-- Generated from authorization-model.json by tools/bootstrap-data/generate-canonical-role-grants.py.
-- Opt-in demo migration only. Does not enable features. Pure MINIAPP grants are preserved.
-- BOTH permissions share a single grant row: canonical Web/BOTH grants are rebuilt together.
DELETE rp FROM sys_role_permission rp JOIN sys_permission p ON p.id=rp.permission_id WHERE p.client_type IN ('WEB','BOTH');
UPDATE sys_role SET data_scope=CASE role_code WHEN 'SYS_ADMIN' THEN 'ALL' WHEN 'SYS_AUDITOR' THEN 'ALL' WHEN 'ORG_ADMIN' THEN 'SCHOOL' WHEN 'TEACHER' THEN 'CLASS' WHEN 'PARENT' THEN 'SELF' WHEN 'PARENT_ADMIN' THEN 'FAMILY' WHEN 'STUDENT' THEN 'SELF' WHEN 'ORG_MEMBER' THEN 'SELF' WHEN 'PLATFORM_USER' THEN 'SELF' END WHERE role_code IN ('SYS_ADMIN','SYS_AUDITOR','ORG_ADMIN','TEACHER','PARENT','PARENT_ADMIN','STUDENT','ORG_MEMBER','PLATFORM_USER');
CREATE TABLE seed_disabled_menu (id BIGINT PRIMARY KEY);
